//! Include under desk_tests; synthetic committed-input calls are not physical IME qualification.
use super::*;
use crate::app::alphabet_host::{load_editor_profile,EditorProfile};
fn loaded(a:&Workspace,pid:&str,record:&Value)->EditorProfile{let answer=Rc::new(RefCell::new(None));let out=answer.clone();load_editor_profile(&a.client,pid.into(),record.clone(),move|r|*out.borrow_mut()=Some(r));wait(||answer.borrow().is_some());let result=answer.borrow_mut().take().unwrap();result}
fn install(a:&Rc<Workspace>,pane:&Rc<EditorPane>){let old=a.panes.borrow_mut().remove(&pane.scene_id);if let Some(old)=old{assert!(!old.dirty.get() && old.pending.get()==0);if let Some(index)=a.pages.page_num(&old.widget){a.pages.remove_page(Some(index));}old.process.stop();}a.panes.borrow_mut().insert(pane.scene_id.clone(),pane.clone());crate::app::desk::bind_pane(pane);wait(||pane.open.get()&&pane.pending.get()==0);a.show_pane(pane.clone(),false);wait(||pane.pending.get()==0);}
pub(super) fn run(binaries:&Path){
    let directory=tempfile::tempdir().unwrap();let data=directory.path().join("alphabet-editor-data");let cache=directory.path().join("alphabet-editor-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let editor=binaries.join(if binaries.join("novel-editor-rust").is_file(){"novel-editor-rust"}else{"novel-editor"});let client=Process::start(&binaries.join(companion),&data,true).unwrap();let novel=rpc(&client,"create_novel",json!({"title":"Checked editor alphabet input"}));let pid=novel["project"]["id"].as_str().unwrap().to_owned();let sid=novel["scene"]["id"].as_str().unwrap().to_owned();let record=rpc(&client,"load_project_scene",json!({"projectId":pid,"sceneId":sid}));let(bytes,license)=(crate::local_resources::tests::synthetic_sfnt(false),crate::local_resources::tests::license_fixture());let(asset,font)=crate::local_resources::prepare_font(&bytes,&license).unwrap();rpc(&client,"put_asset",json!({"projectId":pid,"asset":asset}));let definition=json!({"schemaVersion":1,"id":"editor-symbols","mappingVersion":1,"name":"Exact editor symbols","scriptId":"synthetic","encoding":"private-use","direction":"rtl","mappings":[{"input":"a","output":"\u{e000}","transliteration":"a"},{"input":"b","output":"\u{f0000}","transliteration":"b"}],"font":font,"glossary":[],"notes":"Synthetic Unicode mapping"});rpc(&client,"save_project_data_checked",json!({"projectId":pid,"kind":"writingSystems","parent":null,"dependencies":[{"entityId":sid,"entityType":"scene","revisionId":record["revisionId"]}],"payload":{"schemaVersion":1,"systems":[definition],"assignments":[{"scene":{"kind":"scene","id":sid},"definitionId":"editor-symbols","mappingVersion":1}]}}));
    let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.open.get()&&p.pending.get()==0));let profile=loaded(&a,&pid,&record);assert!(profile.notice.is_none());let p=EditorPane::new_with_profile(&editor,&cache,&record,profile).unwrap();install(&a,&p);let source=p.frame.borrow()["document"].clone();assert_eq!(p.alphabet_profile.as_ref().unwrap().definition,Some(definition.clone()));assert_eq!(p.editor_options.borrow().writing_system["fontFamily"],font["family"]);let private_font=PathBuf::from(p.editor_options.borrow().fonts[0]["path"].as_str().unwrap());assert_eq!(std::fs::read(&private_font).unwrap(),bytes);#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;assert_eq!(std::fs::metadata(private_font.parent().unwrap().parent().unwrap()).unwrap().permissions().mode()&0o077,0);}
    let marker=rpc(&a.client,"sync_cursor",json!({}));p.commit_ordinary("a b عَ 中文 e\u{301}").unwrap();wait(||p.pending.get()==0);let mapped=p.frame.borrow()["document"].clone();assert_eq!(novel_storage::plain_text(&mapped),"\u{e000} \u{f0000} عَ 中文 e\u{301}");assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(rpc(&a.client,"load_project_scene",json!({"projectId":pid,"sceneId":sid})),record);p.operation(json!({"type":"command","command":"undo"}),true);wait(||p.pending.get()==0);assert_eq!(p.frame.borrow()["document"],source);p.operation(json!({"type":"command","command":"redo"}),true);wait(||p.pending.get()==0);assert_eq!(p.frame.borrow()["document"],mapped);
    // Clipboard/drop/palette/replacement all use the existing literal request path.
    p.operation(json!({"type":"text","text":"a b 👩🏽‍🚀"}),true);wait(||p.pending.get()==0);assert!(novel_storage::plain_text(&p.frame.borrow()["document"]).contains("a b 👩🏽‍🚀"));p.operation(json!({"type":"command","command":"undo"}),true);wait(||p.pending.get()==0);assert_eq!(p.frame.borrow()["document"],mapped);
    let fonts=p.editor_options.borrow().fonts.clone();let mapping=p.alphabet_profile.as_ref().unwrap().definition.clone();a.detach_current();let child=last_window();assert!(Rc::ptr_eq(child.active.borrow().as_ref().unwrap(),&p));assert_eq!(p.editor_options.borrow().fonts,fonts);assert_eq!(p.alphabet_profile.as_ref().unwrap().definition,mapping);a.close();wait(||windows()==1);p.commit_ordinary("b").unwrap();wait(||p.pending.get()==0);save(&child,&p);let saved=rpc(&child.client,"load_project_scene",json!({"projectId":pid,"sceneId":sid}));assert_eq!(saved["scene"]["document"],p.frame.borrow()["document"]);
    // An explicitly unavailable font keeps the checked mapping, literal input and
    // persistent capability notice. Stored scene text is never mapped on open.
    let mut unavailable=loaded(&child,&pid,&saved);unavailable.asset=None;unavailable.notice=Some("Custom font unavailable; default fonts preserve exact writing.".into());let fallback=EditorPane::new_with_profile(&editor,&cache,&saved,unavailable).unwrap();install(&child,&fallback);assert_eq!(fallback.frame.borrow()["document"],saved["scene"]["document"]);assert_eq!(fallback.editor_options.borrow().fonts,json!([]));assert!(fallback.error.text().contains("default fonts"));fallback.operation(json!({"type":"text","text":"a"}),true);wait(||fallback.pending.get()==0);assert!(novel_storage::plain_text(&fallback.frame.borrow()["document"]).contains('a'));assert!(fallback.error.text().contains("default fonts"));
    // A wrapper refuses registration once and delegates the default-font open to
    // the real helper. Fallback happens before any input, retaining one-step Undo.
    let wrapper=directory.path().join("refuse-registration.py");let script=format!("#!/usr/bin/python3\nimport json,subprocess,sys\np=subprocess.Popen([{},sys.argv[1]],stdin=subprocess.PIPE,stdout=subprocess.PIPE,text=True)\nfor line in sys.stdin:\n v=json.loads(line)\n if v.get('type')=='open' and v.get('fonts'):\n  print(json.dumps({{'ok':False,'error':'Synthetic font registration refusal'}}),flush=True)\n else:\n  p.stdin.write(line);p.stdin.flush();print(p.stdout.readline().rstrip('\\n'),flush=True)\np.stdin.close();p.wait()\n",serde_json::to_string(&editor.to_string_lossy()).unwrap());std::fs::write(&wrapper,script).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(&wrapper,std::fs::Permissions::from_mode(0o700)).unwrap();}let rejected=EditorPane::new_with_profile(&wrapper,&cache,&saved,loaded(&child,&pid,&saved)).unwrap();wait(||rejected.open.get()&&rejected.pending.get()==0);assert_eq!(rejected.editor_options.borrow().fonts,json!([]));assert!(rejected.error.text().contains("registration failed"));assert_eq!(rejected.frame.borrow()["document"],saved["scene"]["document"]);rejected.operation(json!({"type":"text","text":"a 中文"}),true);wait(||rejected.pending.get()==0);rejected.operation(json!({"type":"command","command":"undo"}),true);wait(||rejected.pending.get()==0);assert_eq!(rejected.frame.borrow()["document"],saved["scene"]["document"]);drop(rejected);
    // The legacy synthetic constructor always leaves ordinary input literal.
    let plain=EditorPane::new(&editor,&cache,&record).unwrap();wait(||plain.open.get()&&plain.pending.get()==0);assert!(plain.alphabet_profile.is_none());plain.commit_ordinary("ab").unwrap();wait(||plain.pending.get()==0);assert_eq!(novel_storage::plain_text(&plain.frame.borrow()["document"]),"ab");drop(plain);
    child.desk.choices.borrow_mut().push_back(SaveChoice::Discard);child.close();wait(||windows()==0);
}
